    <script>
    function toggleSection2NotUsed(whichclass){

        var showClasses = document.querySelectorAll('.'+whichclass);

        var hideClasses;

        if(whichclass === 'krishna'){
            var hideClasses = document.querySelectorAll('.arjuna,.sanjaya,.dritarashtra')
        }
        else if(whichclass === 'arjuna'){
            var hideClasses = document.querySelectorAll('.krishna,.sanjaya,.dritarashtra')
        }
        else if(whichclass === 'sanjaya'){
            var hideClasses = document.querySelectorAll('.arjuna,.krishna,.dritarashtra')
        }
        else if(whichclass === 'dritarashtra'){
            var hideClasses = document.querySelectorAll('.arjuna,.sanjaya,.krishna')
        }

        for (var i = 0; i < hideClasses.length; i ++) {
            hideClasses[i].style.display = 'none';
        }
        for (var i = 0; i < showClasses.length; i ++) {
            showClasses[i].style.display = 'block';
        }
    }

    function toggleSection(whichclass){
        var appClasses = document.getElementsByClassName(whichclass);

        for (var i = 0; i < appClasses.length; i ++) {
            if(appClasses[i].style.display === 'none'){
                appClasses[i].style.display = 'block';
            }
            else{
                appClasses[i].style.display = 'none';
            }
        }   
    }

    $(document).ready(function () {
        $(".b1,.b2,.b3,.b4,.b5,.b6,.b7,.b8,.b9,.b10,.b11,.b12,.b13,.b14,.b15,.b16,.b17,.b18").show();

        $("#krishna,#arjuna,#sanjaya,#dritarashtra").click(function() {
                $(".b1,.b2,.b3,.b4,.b5,.b6,.b7,.b8,.b9,.b10,.b11,.b12,.b13,.b14,.b15,.b16,.b17,.b18").show();
                $(this).toggleClass("inactive lang-btn");
                toggleSection(this.id);
            });

        $("#b1,#b2,#b3,#b4,#b5,#b6,#b7,#b8,#b9,#b10,#b11,#b12,#b13,#b14,#b15,#b16,#b17,#b18").click(function() {
            $(this).toggleClass("inactive lang-btn");
            var text = $(this).text();
            if(text == '+'){
                $(this).text("-");
            }else{
                $(this).text("+");
            }

            $('.'+this.id).slideToggle();
        });

    })

</script>

    
